{
  "canonicalScope": "https://reference.invalid/acme/",
  "store": "one actual absolute mkdtemp directory/transaction.sqlite; identical path create true then false; no copy/reset/new Scope",
  "descriptors": [
    {
      "suffix": "types/bead",
      "describes": "bead",
      "conformsTo": [],
      "propertiesSchema": "schemas/n"
    },
    {
      "suffix": "types/owner",
      "describes": "bead",
      "conformsTo": [],
      "propertiesSchema": "schemas/n",
      "ownsOutgoing": {
        "types/owned": {
          "max": 32
        }
      }
    },
    {
      "suffix": "types/link",
      "describes": "link",
      "conformsTo": [],
      "propertiesSchema": "schemas/n",
      "source": {
        "conformsTo": [],
        "external": "none"
      },
      "target": {
        "conformsTo": [],
        "external": "none"
      }
    },
    {
      "suffix": "types/owned",
      "describes": "link",
      "conformsTo": [],
      "propertiesSchema": "schemas/n",
      "source": {
        "conformsTo": [],
        "external": "none"
      },
      "target": {
        "conformsTo": [],
        "external": "none"
      }
    }
  ],
  "schema": {
    "relativeId": "schemas/n",
    "type": "object",
    "properties": {
      "n": {
        "type": "number"
      }
    },
    "required": [
      "n"
    ],
    "additionalProperties": false
  },
  "credentials": {
    "count": 1,
    "principal": "writer",
    "canMutate": true,
    "token": "fresh high-entropy base64url, never emitted; SAME actual token for both children"
  },
  "runtimeCapture": {
    "port": 0,
    "authorityMode": "canonical",
    "host": "127.0.0.1",
    "profile": "transactional",
    "history": false,
    "scopeAggregateMaximumEndpointMultiplicity": [],
    "readPolicy": "existing generation0 all-visible policy; no transition invoked",
    "testSeams": "none"
  },
  "identityChecks": [
    "initial and reopened installedTransactionBinding must succeed",
    "full served binding equality and runtimeConfigurationIdentity equality, payload/contracts/policy/auth identities equal",
    "same actual canonicalScope, directory/store path, four descriptors/schema and credential association; create and physical listen port are lifecycle differences",
    "actual receipt bodies preserve recorded epoch/view/disposition and exact original next URL; current response header observations remain serving facts"
  ],
  "limits": {
    "exchangeMs": 5000,
    "responseBodyBytes": 1048576,
    "responseHeaderBytes": 65536,
    "derivedResponseWireBytes": 1179648,
    "requestHeaderBytes": 16384,
    "requestBodyBytes": 65536,
    "source": "test143–150; executor156,173–175,898; retain defaults, no widening or new maxWire option"
  },
  "nonClaims": [
    "ownsOutgoing max32 is not a Scope endpoint aggregate",
    "one actual owned Link is updated; this does not exercise a full 32-owned-Link capacity boundary",
    "ordinary Link deletion is not owned Link deletion/cascade",
    "private ready.targets gives ZERO cold-navigation credit",
    "no arbitrary grant policy, public admission, administrative erasure or logical restore credit"
  ]
}

{
  "state": "READ-ONLY proposed chronology; no calls executed",
  "rows": [
    {
      "id": "C0",
      "phase": "Before work",
      "requirement": "Module entry/source fallback currently precedes callback; candidate source and installed entry must be explicitly externally bound before import. Cache bounded metadata within 90s before launch. No Git/readfile subprocess in finally."
    },
    {
      "id": "C1",
      "phase": "Launch attempt1",
      "requirement": "Record attempt before await. No handle/PID is yet acquired. On rejection record ready unavailable/acquisition unknown; preserve store; root owns actual descendant inventory/cleanup."
    },
    {
      "id": "C2",
      "phase": "Acquire child1",
      "requirement": "Immediately after returned handle synchronously retain ChildProcess + exact PID + generation, attach exit and close listeners before assertions or next await. Snapshot exitCode/signalCode; do not infer close event from exitCode/killed/disconnected. Already-lost event => unknown/failclosed."
    },
    {
      "id": "C3",
      "phase": "Requests1–28",
      "requirement": "Assign ordinal before execute invocation. Track actual Promise in pending, increment settled on either resolution/rejection, remove in both branches. Record returned status/headers/body/wire/writeState before assertions. Reject row records fixed error category/writeState if exposed; no partial response bytes invented by a throw-only executor."
    },
    {
      "id": "C4",
      "phase": "Pre-reopen barrier",
      "requirement": "Require pending0 and actual 28 completed response rows, await existing child.close() AND separate actual close-event drain under remaining 90s work, at most10s. Require exit and close code0/signalnull for same owned child. Unknown/failed first closure forbids launch2/store removal."
    },
    {
      "id": "C5",
      "phase": "Launch attempt2 / acquire2",
      "requirement": "Only after C4. Same canonicalScope, exact directory/transaction.sqlite, actual artifacts and actual credential; createfalse. Attach same lifecycle records before further await. Do not require a new physical port; OS may reuse one. Compare full served/config identity."
    },
    {
      "id": "C6",
      "phase": "Requests29–32",
      "requirement": "Use actual original receipt ID and next URL and same success/failure keys/payloads; four actual replay/read responses. No fabricated/IPC body used as receipt evidence."
    },
    {
      "id": "C7",
      "phase": "Final cleanup",
      "requirement": "At most10s after work stops: abort work, stop new requests, drain registered request Promises and existing close+actual child close. Aggregate errors once; never retry child.close because helper caches promise. Test cleanup timeout is not proof helper background cleanup settled."
    },
    {
      "id": "C8",
      "phase": "Store/report barrier",
      "requirement": "Remove directory only if every attempt has known acquisition disposition, every acquired child has observed clean exit+close, every request/close promise settled, and no unknown owner remains. Catch removal error and emit removed/retained/unknown truthfully; rm success does not prove owner close. Serialize cached success/failure report after finally before AggregateError."
    },
    {
      "id": "C9",
      "phase": "Root terminal audit",
      "requirement": "Root future supervisor independently observes test runner exit+close and exact owned descendants, checks no surviving children/pending helper cleanup and final store disposition. Unknown survivor/cleanup means failed evidence, not successful qualification."
    }
  ],
  "currentFacts": {
    "launcher": "10s ready/exit wait; timeout SIGKILL then failure drain may wait another10s; close cached, resolves on clean exit only, not stdio close; startup error does not return child handle",
    "runtimeClose": "listener close+closeAllConnections → pending HTTP settled → service close → streams/active drained → read close → owner.close/db.close; installed process awaits runtime.close before disconnect/main completion",
    "currentTest": "first close at395 then reopen397; final close443; report constructed418 before cleanup; unconditional rm449; success console only453",
    "notDirectOwnerTelemetry": "Graceful child exit0 plus observed close and inspected bootstrap/runtime/service/store control flow support shutdown; no fabricated direct SQLite-close receipt or socket-close count."
  },
  "budgets": {
    "workMs": 90000,
    "callbackMs": 120000,
    "exchangeMs": 5000,
    "launcherReadyMs": 10000,
    "launcherCloseExitWaitMs": 10000,
    "launcherFailureDrainAdditionalMs": 10000,
    "proposedCallbackCleanupMs": 10000,
    "rootOuterProposalMs": 150000,
    "rootTermProposalMs": 145000,
    "rootKillProposalMs": 149000,
    "proposalStatus": "CLOSED, requires root mechanical acceptance; 120s callback + reporting/owned-descendant audit allowance. Do not reuse startup120/TERM115; never autoextend/retry. Native callback timeout itself does not guarantee async finally completion."
  },
  "ownershipUnknownPolicy": "No speculative kill, no invented acquisition count, no rm when unknown; root exact-owned-identity supervisor cleanup required before another attempt."
}

{
  "preservedFiveLocalOracles": [
    {
      "id": "O1",
      "lines": [
        253,
        264
      ],
      "mutant": "omit last receipt result",
      "failure": "exact ordered 33-entry oracle"
    },
    {
      "id": "O2",
      "lines": [
        273,
        276
      ],
      "mutant": "omit first delete Event",
      "failure": "exact96fact sequence"
    },
    {
      "id": "O3",
      "lines": [
        277,
        283
      ],
      "mutant": "swap first two complete 3-Event Link groups",
      "failure": "exact canonical Link fact order"
    },
    {
      "id": "O4",
      "lines": [
        355,
        369
      ],
      "mutant": "mutually consistent actual n0 prestate, stale receipt/source/live Link",
      "failure": "labeled requested owned Link properties literal n1 assertion"
    },
    {
      "id": "O5",
      "lines": [
        370,
        372
      ],
      "mutant": "wrong sourceRevision",
      "failure": "sourceRevision equals actual live owner revision"
    }
  ],
  "mechanicsStaticReviewCases": [
    {
      "id": "M1",
      "counterfactual": "non200 or wrong200 header response",
      "must": "actual response is recorded before assertion; callback fails with actual received count, not synthetic missing response"
    },
    {
      "id": "M2",
      "counterfactual": "execute rejects/aborts before response",
      "must": "attempted1/settled1/received0 with unavailable response fields, pending0 when settled; no fabricated bytes/body/status/completewrite"
    },
    {
      "id": "M3",
      "counterfactual": "close promise resolves on exit before stdio close",
      "must": "no reopen/removal until separate actual close; exit is not close"
    },
    {
      "id": "M4",
      "counterfactual": "first child shutdown unknown or nonzero",
      "must": "second launch forbidden, store retained, failure report survives"
    },
    {
      "id": "M5",
      "counterfactual": "launch rejects before handle returns",
      "must": "attempt true/acquisition unknown/closure unknown, not two acquired children or clean owner; preserve directory; root audit required"
    },
    {
      "id": "M6",
      "counterfactual": "cleanup wait timeout or removal throws",
      "must": "fixed stage failure aggregates; pending/unresolved truth retained; no success log/clean claim"
    },
    {
      "id": "M7",
      "counterfactual": "cached source/diff/entry metadata capture unavailable",
      "must": "fixed nullReason + failure before launch; no invented hashes, no throwing subprocess in finally"
    }
  ],
  "execution": "none; these are finite review predicates, no additional product requests/tests/mutant runtime authorized"
}

