1	/** Actual private set serving observations; no ordinary runner/catalog/profile admission. */
2	import { execFileSync, type ChildProcess } from "node:child_process";
3	import { createHash, randomBytes } from "node:crypto";
4	import { mkdtempSync, readFileSync, realpathSync, rmSync } from "node:fs";
5	import { tmpdir } from "node:os";
6	import path from "node:path";
7	import { fileURLToPath } from "node:url";
8	import { expect, it } from "vitest";
9	import { Ajv2020 } from "ajv/dist/2020.js";
10	import { createRawHttpExchangeExecutor } from "@bdp/conformance";
11	import { isJsonSchemaUri, isJsonSchemaDateTime } from "@bdp/protocol";
12	import { installedTransactionBinding } from "../test-support/transactional-execution-binding.js";
13	const root = fileURLToPath(new URL("../../../", import.meta.url));
14	const { launchInstalledTransaction } = (await import(
15	  new URL("../../../scripts/transaction-installed-observation.mjs", import.meta.url).href
16	)) as {
17	  launchInstalledTransaction(
18	    entry: string,
19	    configuration: unknown,
20	    signal: AbortSignal,
21	  ): Promise<{ child: ChildProcess; ready: Record<string, unknown>; close(): Promise<void> }>;
22	};
23	const entry = realpathSync(
24	  process.env.BDP_TRANSACTIONAL_INSTALLED_ENTRY ??
25	    path.join(root, "packages/server/dist/transaction-installed-process.js"),
26	);
27	if (process.env.BDP_TRANSACTIONAL_INSTALLED_ENTRY && !process.env.BDP_TRANSACTIONAL_SOURCE_COMMIT)
28	  throw Error("installed set override requires explicit source commit");
29	const source =
30	  process.env.BDP_TRANSACTIONAL_SOURCE_COMMIT ??
31	  execFileSync("git", ["rev-parse", "HEAD"], { cwd: root, encoding: "utf8" }).trim();
32	const fixture = {
33	  bytes: readFileSync(
34	    path.join(root, "packages/conformance/test-support/transactional/fixture-v1.json"),
35	  ),
36	};
37	const scope = "https://reference.invalid/acme/",
38	  bead = `${scope}types/bead`,
39	  owner = `${scope}types/owner`,
40	  link = `${scope}types/link`,
41	  owned = `${scope}types/owned`,
42	  schema = `${scope}schemas/n`;
43	const descriptors = [
44	  { id: bead, name: "Bead", describes: "bead", conformsTo: [], propertiesSchema: schema },
45	  {
46	    id: owner,
47	    name: "Owner",
48	    describes: "bead",
49	    conformsTo: [],
50	    propertiesSchema: schema,
51	    ownsOutgoing: { [owned]: { max: 32 } },
52	  },
53	  ...[link, owned].map((id) => ({
54	    id,
55	    name: id.endsWith("owned") ? "Owned" : "Link",
56	    describes: "link",
57	    conformsTo: [],
58	    propertiesSchema: schema,
59	    source: { conformsTo: [], external: "none" },
60	    target: { conformsTo: [], external: "none" },
61	  })),
62	];
63	const artifacts = {
64	  descriptors: descriptors.map((d) => ({ retrievalUri: d.id, utf8: JSON.stringify(d) })),
65	  schemas: [
66	    {
67	      retrievalUri: schema,
68	      utf8: JSON.stringify({
69	        $id: schema,
70	        type: "object",
71	        properties: { n: { type: "number" } },
72	        required: ["n"],
73	        additionalProperties: false,
74	      }),
75	    },
76	  ],
77	};
78	const ajv = new Ajv2020({ strict: true, allErrors: true });
79	ajv.addFormat("uri", { type: "string", validate: isJsonSchemaUri });
80	ajv.addFormat("date-time", { type: "string", validate: isJsonSchemaDateTime });
81	const bundle = JSON.parse(readFileSync(path.join(root, "schemas/bdp-v0.schema.json"), "utf8"));
82	ajv.addSchema(bundle);
83	const validators = Object.fromEntries(
84	  ["mutationReceipt", "mutationReceiptPage", "eventPage", "changeGroup"].map((name) => [
85	    name,
86	    ajv.compile({ $ref: `${bundle.$id}#/$defs/${name}` }),
87	  ]),
88	);
89	function object(value: unknown): Record<string, unknown> {
90	  if (!value || typeof value !== "object" || Array.isArray(value))
91	    throw Error("expected wire object");
92	  return value as Record<string, unknown>;
93	}
94	function array(value: unknown): Record<string, unknown>[] {
95	  if (!Array.isArray(value)) throw Error("expected wire array");
96	  return value.map(object);
97	}
98	function checked(name: string, value: unknown) {
99	  const validate = validators[name];
100	  if (!validate) throw Error("validator missing");
101	  expect(validate(value), JSON.stringify(validate.errors)).toBe(true);
102	}
103	it("installed valid sets preserve atomic effects, original receipts, owned versions and complete paged Events", async () => {
104	  const controller = new AbortController(),
105	    deadline = setTimeout(
106	      () => controller.abort(new Error("installed set cohort deadline")),
107	      90000,
108	    );
109	  const directory = mkdtempSync(path.join(tmpdir(), "bdp-set-installed-")),
110	    token = randomBytes(32).toString("base64url");
111	  const configuration = {
112	    scope,
113	    directory,
114	    create: true,
115	    artifacts,
116	    credentials: [{ token, principal: "writer", canMutate: true }],
117	  };
118	  let child: Awaited<ReturnType<typeof launchInstalledTransaction>> | undefined;
119	  const failures: unknown[] = [],
120	    observations: unknown[] = [];
121	  let report: unknown,
122	    key = 0;
123	  try {
124	    child = await launchInstalledTransaction(entry, configuration, controller.signal);
125	    const initialReady = child.ready,
126	      binding = installedTransactionBinding(initialReady, source, fixture);
127	    expect(Object.keys(initialReady.targets as object)).toHaveLength(12);
128	    const send = async (
129	      target: string,
130	      body?: unknown,
131	      suppliedKey?: string,
132	      expectedStatus = 200,
133	    ) => {
134	      if (!child) throw Error("closed installed session");
135	      const current = installedTransactionBinding(child.ready, source, fixture);
136	      expect(current.runtimeConfigurationIdentity).toBe(binding.runtimeConfigurationIdentity);
137	      const address = new URL(child.ready.listenUrl as string),
138	        url = new URL(target, scope).href,
139	        method = body === undefined ? ("GET" as const) : ("POST" as const);
140	      const execute = createRawHttpExchangeExecutor(
141	        { transport: "plain", host: address.hostname, port: Number(address.port) },
142	        {
143	          requestTimeoutMs: 5000,
144	          maximumBodyBytes: 1048576,
145	          exactMode: {
146	            scope,
147	            profile: "transactional",
148	            routes: [{ method, url }],
149	            maximumRequestHeaderBytes: 16384,
150	            maximumRequestBodyBytes: 65536,
151	            defaultCredentialRef: "writer",
152	            credentialHandles: [{ id: "writer", headerNames: ["authorization"] }],
153	            resolveCredentials: () => ({ authorization: `Bearer ${token}` }),
154	          },
155	        },
156	      );
157	      const requestBody = typeof body === "string" ? body : JSON.stringify(body);
158	      const response = await execute({
159	        method,
160	        url,
161	        signal: controller.signal,
162	        credentialRef: "writer",
163	        raw: {
164	          headerLines:
165	            body === undefined
166	              ? []
167	              : [
168	                  { name: "Content-Type", value: "application/json" },
169	                  { name: "Idempotency-Key", value: suppliedKey ?? `set_${key++}` },
170	                ],
171	          ...(body === undefined ? {} : { bodyBytes: Buffer.from(requestBody!) }),
172	        },
173	      });
174	      expect(response.status, response.bodyText).toBe(expectedStatus);
175	      expect(response.exactRequest?.writeState).toBe("complete");
176	      expect(response.wireResponseBytes?.length).toBeGreaterThan(0);
177	      if (expectedStatus === 200)
178	        for (const header of ["bdp-scope-epoch", "bdp-authorization-view", "bdp-scope-position"])
179	          expect(response.headers[header]?.length).toBeGreaterThan(0);
180	      observations.push({
181	        method,
182	        url,
183	        requestBody,
184	        status: response.status,
185	        headers: response.headers,
186	        body: response.bodyText,
187	        wireResponseBase64: Buffer.from(response.wireResponseBytes!).toString("base64"),
188	        wireSha256: createHash("sha256").update(response.wireResponseBytes!).digest("hex"),
189	      });
190	      const parsed = object(JSON.parse(response.bodyText));
191	      if (method === "POST" && expectedStatus === 200) checked("mutationReceipt", parsed);
192	      return parsed;
193	    };
194	    const run = (operations: unknown[], suppliedKey?: string) =>
195	      send("operations/batch", { operations }, suppliedKey);
196	    const create = (id: string, type = bead) => ({
197	      operation: "createBead",
198	      id: `beads/${id}`,
199	      type,
200	      properties: { n: 0 },
201	      metadata: { stable: true },
202	    });
203	    await run([create("a"), create("b"), create("owner", owner)]);
