    const linkIds = Array.from(
      { length: 32 },
      (_, i) => `${scope}links/l${String(i).padStart(2, "0")}`,
    );
    await run(
      linkIds.map((id) => ({
        operation: "createLink",
        id,
        type: link,
        source: "beads/a",
        target: "beads/b",
        properties: { n: 0 },
      })),
    );
